WITH parsed AS (SELECT id, customer_id, created_at, items, ship_to, attributes, ship_to.country AS ship_country, attributes['utm_source'] AS utm_source, ship_to.city AS ship_city FROM carts) SELECT *, ROW_NUMBER() OVER (ORDER BY created_at DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY ship_country, ship_city ORDER BY created_at DESC, id) AS event_seq_2, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id) AS seq_no_2, ROW_NUMBER() OVER (PARTITION BY ship_country, ship_city ORDER BY created_at DESC, id) AS row_seq FROM parsed
